import os   # 파일/폴더 경로를 다루는 기본 도구 (예: 이 파일이 어디 있는지 찾기)
import re   # 정규표현식(regex) 도구. 문장 속에서 특정 패턴(ㅋㅋㅋ, ~~~ 등)을 찾을 때 사용
import sys  # 파이썬 실행 환경 자체를 다루는 도구 (여기서는 콘솔 출력 인코딩 설정에만 사용)

import joblib       # 학습이 끝난 모델을 파일(.pkl)로 저장하고, 나중에 다시 불러오는 도구
import numpy as np  # 숫자 배열(벡터, 행렬) 계산을 빠르게 해주는 도구. "np"라는 별명으로 사용
