# 6. CSV 데이터 불러오기 및 정리
# ==========================================================

print()
print("[1/6] 데이터 불러오는 중...")
print(f"      파일 경로 : {DATA_PATH}")

# 학습용 CSV 파일이 실제로 존재하는지 먼저 확인합니다.
# 없으면 뒤에서 알 수 없는 에러로 죽는 대신, 여기서 명확한 안내와 함께
# 프로그램을 멈춥니다(raise = 에러를 강제로 발생시킴).
if not os.path.exists(DATA_PATH):
    raise FileNotFoundError(
        "\nCSV 파일을 찾을 수 없습니다.\n"
        f"현재 경로:\n{DATA_PATH}\n\n"
        "DATA_PATH를 실제 파일 위치로 수정하세요."
    )

# CSV 파일을 표(DataFrame) 형태로 읽어옵니다.
# df는 "text"열과 "label"열을 가진 표라고 생각하면 됩니다.
df = pd.read_csv(DATA_PATH, encoding="utf-8")

print(f"      기본 데이터 : {len(df)}행")

# ----- 존댓말 보강 데이터 병합 -----
#
# 원본 데이터는 label=0이 전부 대학생 반말 채팅이라
# "존댓말 = 영포티"로 학습되는 문제가 있습니다.
# 영포티가 아닌 존댓말(업무/공지/문의) 문장을 label=0으로 보강해
# 존댓말 자체가 영포티 신호가 되지 않도록 바로잡습니다.

if os.path.exists(POLITE_PATH):
    # 보강용 CSV가 있으면 읽어서
    df_polite = pd.read_csv(POLITE_PATH, encoding="utf-8")
    # 기존 데이터(df) 아래에 이어붙입니다 (표 2개를 세로로 합치는 것과 같음)
    # ignore_index=True → 합친 뒤 행 번호(인덱스)를 0부터 새로 매김
    df = pd.concat([df, df_polite], ignore_index=True)
    print(f"      존댓말 보강 : {len(df_polite)}행 추가")
else:
    # 파일이 없어도 프로그램은 죽지 않고 그냥 넘어갑니다.
    print("      존댓말 보강 : 파일이 없어 건너뜁니다.")

before = len(df)  # 정리(청소) 작업 전의 행 개수를 기록해둠 (나중에 비교용)

# ----- 데이터 정리(cleaning) 4단계 -----
# 실제 데이터에는 종종 빈 값, 중복, 공백만 있는 문장 등
# "학습에 방해가 되는" 지저분한 부분이 섞여 있습니다. 아래에서 정리합니다.

# 1) text 또는 label 값이 비어있는(NaN) 행은 통째로 제거
df = df.dropna(subset=["text", "label"])

# 2) text 열의 값을 전부 문자열로 강제 변환하고, 앞뒤 공백 제거
df["text"] = df["text"].astype(str).str.strip()

# 3) 위 strip() 이후 완전히 빈 문자열("")만 남은 행은 제거
df = df[df["text"] != ""]

# 4) 완전히 똑같은 문장이 중복으로 여러 번 있으면 1개만 남기고 제거
#    reset_index(drop=True) → 중복 제거로 행 번호가 듬성듬성해진 것을
#                              다시 0, 1, 2, ... 순서로 깔끔하게 정리
df = df.drop_duplicates(subset="text").reset_index(drop=True)

# label 값이 문자열("1")이나 실수(1.0)로 들어와 있을 수 있으므로
# 정수(int)로 확실히 통일합니다.
df["label"] = df["label"].astype(int)

print(f"      전체 {before}행 → 정리 후 {len(df)}행 (중복/결측 {before - len(df)}행 제거)")
print(f"      일반(0)  : {int((df['label'] == 0).sum())}개")
print(f"      영포티(1): {int((df['label'] == 1).sum())}개")


# ==========================================================
# 7. Multi-hot 벡터로 변환
# ==========================================================
# 이제 위 3~4단계에서 만든 함수(text_to_multihot, transform_texts)를
# 실제로 데이터 전체에 적용합니다.

print()
print("[2/6] Multi-hot 벡터로 변환하는 중...")

# X: 입력값(문장을 숫자로 바꾼 것). (문장 수, 28) 크기의 숫자 표.
#    머신러닝에서 관례적으로 "입력(feature)"은 대문자 X로 씁니다.
X = transform_texts(df["text"].tolist())

# y: 정답값(label). 문장 수만큼의 0/1 배열.
#    머신러닝에서 관례적으로 "정답(label)"은 소문자 y로 씁니다.
y = df["label"].to_numpy()

print(f"      벡터 행렬 크기 : {X.shape}  (문장 수 × 특징 수)")

# X.sum(axis=1) → 각 문장(행)마다 28개 특징 값을 다 더한 값 (특징이 하나라도
#                 있으면 0보다 커짐)
# > 0            → 특징이 1개 이상 검출됐는지 True/False로 변환
# .mean() * 100  → True 비율을 백분율(%)로 계산
coverage = (X.sum(axis=1) > 0).mean() * 100
print(f"      특징이 1개 이상 검출된 문장 비율 : {coverage:.1f}%")

# 아래는 "실제로 벡터화가 잘 되고 있는지" 눈으로 확인하기 위한 예시 출력입니다.
# y == 1인 것들(영포티 문장) 중 맨 처음 나오는 위치를 찾습니다.
# np.argmax(y == 1) → y가 [0,0,1,0,1,...] 이라면 처음 True(1)가 나오는
#                       인덱스인 2를 반환 (True를 1, False를 0으로 보고
#                       가장 큰 값이 처음 나오는 위치를 찾는 원리)
sample_idx = int(np.argmax(y == 1))
print()
print("      [변환 예시]")
print(f"      문장   : {df['text'].iloc[sample_idx]}")
print(f"      벡터   : {X[sample_idx].astype(int).tolist()}")


# ==========================================================
# 8. Train / Test 데이터 분할
# ==========================================================
# [핵심 개념] 왜 데이터를 나누는가?
#
# 모델을 "학습에 쓴 문제로 다시 시험 보게" 하면 answer를 외워서
# 맞추는 것처럼 실제 실력보다 점수가 부풀려집니다(과적합, overfitting).
# 그래서 데이터를 미리 두 그룹으로 나눠서
#   - 학습용(train): 모델이 패턴을 배우는 데 사용
#   - 검증용(test) : 모델이 "한 번도 안 본 문제"로 실력을 테스트하는 데 사용
# 이렇게 나눠서 채점해야 실제 성능을 신뢰할 수 있습니다.

print()
print("[3/6] 학습/검증 데이터 분할 중... (8:2, stratify=y)")

X_train, X_test, y_train, y_test = train_test_split(
    X,
    y,
    test_size=0.2,       # 전체의 20%를 검증용(test)으로, 나머지 80%는 학습용(train)으로
    random_state=RANDOM_STATE,  # 위에서 정의한 42. 항상 같은 방식으로 나뉘게 고정
    stratify=y,           # [중요] label(0/1) 비율을 train/test 양쪽에 동일하게 유지
                           # (안 그러면 예를 들어 test에 영포티 문장이 거의 안 들어가서
                           #  성능 평가가 왜곡될 수 있음)
)

print(f"      학습 데이터 : {X_train.shape[0]}개")
print(f"      검증 데이터 : {X_test.shape[0]}개")


# ==========================================================
# 9. 모델 3종 학습 및 성능 비교
# ==========================================================
# [핵심 개념] 왜 모델을 3개나 비교하는가?
#
# 어떤 모델이 이 데이터에 가장 잘 맞을지는 미리 알 수 없기 때문에,
# 성격이 다른 3가지 모델을 모두 학습시켜서 성능을 비교해보고
# 그중 가장 적합한 것을 최종으로 고릅니다.
#
#   - LogisticRegression (로지스틱 회귀)
#     : 각 특징에 "가중치(계수)"를 매겨서 점수를 계산.
#       "이 특징이 몇 점을 올렸는지" 설명하기 매우 쉬움 → 해석력 최고
#
#   - DecisionTreeClassifier (의사결정나무)
#     : "느낌표가 2번 이상이고 & 라떼가 1번 이상이면 영포티" 같은
#       if-else 규칙 트리를 만듦 → 사람이 읽기 쉬운 규칙 형태
#
#   - RandomForestClassifier (랜덤 포레스트)
#     : 의사결정나무를 200개(n_estimators=200) 만들어서 다수결로 결정.
#       보통 의사결정나무 하나보다 더 안정적이고 정확함(과적합 방지)

print()
print("[4/6] 모델 3종 학습 및 비교 중...")

candidates = {
    "LogisticRegression": LogisticRegression(max_iter=1000, random_state=RANDOM_STATE),
    # max_iter=1000 → 모델이 최적의 가중치를 찾기 위해 반복 계산을
    #                 최대 1000번까지 시도하도록 허용 (너무 적으면
    #                 "수렴하지 못했다"는 경고가 뜰 수 있음)

    "DecisionTree": DecisionTreeClassifier(max_depth=6, random_state=RANDOM_STATE),
    # max_depth=6 → 나무가 질문을 최대 6단계까지만 깊게 파고들도록 제한.
    #               제한을 안 두면 나무가 너무 복잡해져서 학습 데이터를
    #               "암기"해버리는 과적합이 발생하기 쉬움

    "RandomForest": RandomForestClassifier(
        n_estimators=200, random_state=RANDOM_STATE
    ),
    # n_estimators=200 → 나무 200그루를 만들어서 다수결 투표로 최종 결정
}

results = {}  # 모델 이름 → (정확도, F1점수) 를 저장할 딕셔너리

# candidates에 담긴 3개 모델을 하나씩 꺼내서 똑같은 과정을 반복합니다.
for name, candidate in candidates.items():
    candidate.fit(X_train, y_train)          # 학습: 학습용 데이터로 패턴을 배움
    pred = candidate.predict(X_test)          # 예측: 검증용 데이터(정답 안 알려줌)로 시험
    results[name] = (accuracy_score(y_test, pred), f1_score(y_test, pred))
    # accuracy_score: 정답을 맞춘 비율
    # f1_score       : 정밀도와 재현율의 균형 점수 (아래 10번 섹션에서 자세히 설명)

print()
print("      " + "-" * 46)
print(f"      {'모델':<22}{'Accuracy':>10}{'F1':>10}")
print("      " + "-" * 46)

for name, (acc, f1) in results.items():
    print(f"      {name:<22}{acc:>10.3f}{f1:>10.3f}")

print("      " + "-" * 46)

# 3개 모델 중 최종적으로 사용할 모델을 선택합니다.
# 성능이 조금 낮더라도 "왜 이 점수가 나왔는지 설명 가능한" 로지스틱
# 회귀를 최종 모델로 채택합니다. (이 프로젝트의 목적이 "판별 + 근거 설명"이기 때문)
model = candidates["LogisticRegression"]

print()
print("      최종 채택 모델 : LogisticRegression")
print("      (계수로 '어떤 특징이 점수를 올렸는지' 설명할 수 있기 때문)")


# ==========================================================
# 10. 최종 모델 성능 평가 (분류 4대 지표)
# ==========================================================
# [핵심 개념] 분류 문제의 4대 평가지표
#
#   - 정확도(Accuracy)  : 전체 중 맞춘 비율. 가장 직관적이지만
#                          label 비율이 한쪽으로 치우치면 오해를 줄 수 있음
#   - 정밀도(Precision) : "영포티다!"라고 예측한 것 중 진짜 영포티였던 비율
#                          (정밀도가 낮으면 "억울한 오해"가 많다는 뜻)
#   - 재현율(Recall)    : 실제 영포티 문장 중 모델이 놓치지 않고 잡아낸 비율
#                          (재현율이 낮으면 "진짜 영포티를 놓친다"는 뜻)
#   - F1-Score          : 정밀도와 재현율의 조화평균(둘 다 챙기는 균형 점수)
#                          데이터가 한쪽 라벨에 치우쳐 있을 때 특히 중요

print()
print("[5/6] 최종 모델 성능 평가")
print()

y_pred = model.predict(X_test)  # 최종 모델(로지스틱 회귀)로 검증용 데이터 예측

print(
    classification_report(
        y_test,
        y_pred,
        target_names=["일반(0)", "영포티(1)"],  # 0/1 대신 사람이 읽을 이름으로 표시
        digits=3,  # 소수점 3자리까지 표시
    )
)

# ----- 특징별 계수(가중치) 전체 출력 -----
# 로지스틱 회귀는 학습이 끝나면 "28개 특징 각각에 얼마의 가중치를
# 부여했는지"를 model.coef_ 라는 배열로 갖고 있습니다.
# 이 값이 클수록(+ 방향) "이 특징이 있으면 영포티일 가능성이 커진다"는 뜻,
# 작을수록(- 방향) "이 특징이 있으면 오히려 영포티가 아닐 가능성이 커진다"는 뜻입니다.
coefficients = model.coef_[0]  # coef_는 2차원 배열이라 [0]으로 1차원만 꺼냄

print("      [특징별 가중치 - 값이 클수록 영포티 신호]")
print("      " + "-" * 46)

# FEATURE_NAMES(이름 28개)와 coefficients(가중치 28개)를 짝지어서(zip)
# 가중치가 큰 순서(내림차순)로 정렬해 출력합니다.
for name, coef in sorted(
    zip(FEATURE_NAMES, coefficients), key=lambda item: item[1], reverse=True
):
    direction = "영포티 ↑" if coef > 0 else "영포티 ↓"
    print(f"      {name:<18}{coef:>+8.2f}   {direction}")

print("      " + "-" * 46)


