joblib.dump(
    {
        "model": model,
        "features": FEATURES,
        "use_typo_correction": USE_TYPO_CORRECTION,
        "fuzzy_keywords": FUZZY_KEYWORDS,
        "aliases": ALIASES,
    },
    MODEL_PATH,
)

print(f"      저장 완료 : {MODEL_PATH}")


# ==========================================================
# 12. 새 문장 판독 함수
# ==========================================================
# 지금까지는 "이미 정답을 아는 데이터"로 모델을 학습/평가했다면,
# 여기서부터는 "정답을 모르는 새 문장"이 들어왔을 때 실제로
# 영포티 점수를 계산해주는 함수를 만듭니다.


def predict_forty(text):
    """
    문장 1개를 판독합니다.

    반환값:
    score        : 영포티 지수 (0~100)
    vector       : 28차원 multi-hot 벡터
    contributions: (특징명, 등장횟수, 계수, 기여도, 오타보정여부) 리스트
                   (기여도 절댓값 내림차순)
    """

    # 1) 입력 문장을 학습 때와 똑같은 방식으로 28차원 벡터로 변환
    #    return_fuzzy_flags=True → 어떤 특징이 오타 보정 덕분에 잡혔는지도 함께 받음
    vector, fuzzy_flags = text_to_multihot(text, return_fuzzy_flags=True)

    # 2) 학습된 모델에 벡터를 넣어서 "영포티(클래스 1)일 확률"을 구함
    #    predict_proba → [[일반일 확률, 영포티일 확률]] 형태의 2차원 배열을 반환하므로
    #    [0][1]로 "첫 번째(유일한) 샘플의, 영포티(index 1)일 확률"만 꺼냄
    #    reshape(1, -1) → 벡터 하나를 "샘플 1개짜리 표"모양((1, 28))으로 바꿔주는 것
    #                      (sklearn은 항상 "여러 개의 샘플이 들어있는 표" 형태를 기대하기 때문)
    #    * 100 → 0~1 사이 확률을 0~100 점수로 변환
    score = model.predict_proba(vector.reshape(1, -1))[0][1] * 100

    contributions = []  # "이 문장에서 실제로 검출된 특징들"만 모아둘 리스트

    # 28개 특징 이름, 이 문장에서의 등장 횟수, 각 특징의 학습된 가중치를
    # 한 번에 짝지어(zip) 순서대로 확인합니다.
    for name, count, coef in zip(FEATURE_NAMES, vector, coefficients):
        if count > 0:  # 실제로 이 문장에서 등장한 특징만 결과에 포함 (0회는 스킵)
            # 기여도 = 등장 횟수 × 가중치
            # → "몇 번 나왔는지"와 "얼마나 중요한 특징인지"를 곱해서
            #    이 특징이 최종 점수에 실제로 얼마나 영향을 줬는지를 나타냄
            #
            # 마지막 값은 "정규식은 놓쳤는데 오타 보정이 잡아낸 특징인가?"입니다.
            contributions.append(
                (name, int(count), coef, count * coef, name in fuzzy_flags)
            )

    # 기여도의 절댓값이 큰 순서(=영향력이 큰 순서)로 정렬
    # (기여도가 음수든 양수든, "영향을 많이 준" 순서로 보여주기 위함)
    contributions.sort(key=lambda item: abs(item[3]), reverse=True)

    return score, vector, contributions


# ==========================================================
# 13. 대화형 판독 루프 (사용자가 실제로 사용하는 부분)
# ==========================================================
# 여기서부터는 콘솔에서 사용자가 문장을 직접 입력하면
# 바로바로 점수를 계산해서 보여주는 "무한 반복 루프"입니다.
# q, exit, quit 중 하나를 입력하거나 Ctrl+C를 누르면 종료됩니다.

print()
print("=" * 70)
print(" [영포티 판독기]  분석할 문장을 입력하세요.")
print(" 종료하려면 q 또는 exit 를 입력하세요.")
print("=" * 70)

while True:  # 사용자가 종료하지 않는 한 계속 반복

    try:
        # 콘솔에서 한 줄 입력을 받고, 앞뒤 공백은 제거
        user_input = input("\n판독할 문장 > ").strip()
    except (EOFError, KeyboardInterrupt):
        # EOFError: 입력 스트림이 예기치 않게 끝난 경우 (예: 파이프로 실행 중 입력 종료)
        # KeyboardInterrupt: 사용자가 Ctrl+C를 누른 경우
        # 둘 다 "더 이상 입력을 받을 수 없다"는 뜻이므로 루프를 정상 종료
        print("\n판독기를 종료합니다.")
        break

    if user_input.lower() in ("q", "exit", "quit"):
        # 대소문자 구분 없이 q/exit/quit 중 하나면 종료
        print("판독기를 종료합니다.")
        break

    if not user_input:
        # 아무것도 입력하지 않고 엔터만 쳤다면, 다시 입력받기(무시하고 계속)
        continue

    # 실제 판독 실행
    score, vector, contributions = predict_forty(user_input)
    grade, comment = get_grade(score)

    print()
    print("-" * 70)
    print(f" 영포티 지수 : {score:.1f}%   [{grade}]")
    print(f" {comment}")
    print("-" * 70)

    if contributions:
        # 검출된 특징이 1개 이상 있으면, 표 형태로 상세 내역을 출력
        print(f" {'검출된 특징':<18}{'횟수':>6}{'가중치':>10}{'기여도':>10}   비고")
        print(" " + "-" * 68)

        for name, count, coef, contribution, is_fuzzy in contributions:
            # 정규식은 놓쳤는데 오타 보정이 잡아낸 특징에는 표시를 붙여줍니다.
            # (왜 이 특징이 잡혔는지 사용자가 알 수 있도록)
            note = "(오타보정)" if is_fuzzy else ""
            print(
                f" {name:<18}{count:>6}{coef:>+10.2f}{contribution:>+10.2f}   {note}"
            )
    else:
        # 검출된 특징이 하나도 없으면 안내 문구만 출력
        print(" 사전에 등록된 특징이 검출되지 않았습니다.")

    print(" " + "-" * 68)
    print(f" multi-hot 벡터 : {vector.astype(int).tolist()}")
    print("-" * 70)
